// Loopback-only protocol experiment. No production endpoint, OAuth or gate bypass.
use serde_json::{Value,json};use std::{net::TcpStream,time::Duration};
fn main(){let mut args=std::env::args().skip(1);let port:u16=args.next().expect("loopback mock port").parse().unwrap();let stream=TcpStream::connect_timeout(&([127,0,0,1],port).into(),Duration::from_secs(2)).unwrap();stream.set_read_timeout(Some(Duration::from_secs(2))).unwrap();stream.set_write_timeout(Some(Duration::from_secs(2))).unwrap();let(mut ws,_)=tungstenite::client(format!("ws://127.0.0.1:{port}/state"),stream).unwrap();ws.send(tungstenite::Message::Text(json!({"rid":"synthetic","updateFullState":{"device":{"info":{"deviceId":"synthetic"},"capabilities":{"canBeRemoteController":true}}}}).to_string().into())).unwrap();let mut result=json!({"status":"unknown"});for _ in 0..32{let Ok(msg)=ws.read()else{break};if let Ok(s)=msg.to_text(){if let Ok(v)=serde_json::from_str::<Value>(s){if v.get("error").is_some(){result=json!({"status":"error","retry_after_seconds":pulse_architecture_lab::cooldown(&v)});break}if let Some(status)=pulse_architecture_lab::classify(&v){result=json!({"status":status});break}}}}let _=ws.close(None);println!("{result}");}
